from pathlib import Path
p=Path(r'C:\New Projet\SMART-MEGA\adjudicate_signal_challenger.py')
s=p.read_text(encoding='utf-8')
s=s.replace('import json\nfrom datetime', 'import json\nimport math\nfrom datetime',1)
insert_after="""from smart_rank_score_calibration import SCHEMA as RANK_CALIBRATION_SCHEMA, UNIFORM_PROB, brier_score, sha256_json as rank_calibration_sha256_json\n\n\n"""
helpers="""def _strict_int(value, label: str, *, lo: int | None = None, hi: int | None = None) -> int:\n    if isinstance(value, bool) or not isinstance(value, int):\n        raise ValueError(f'{label} must be an integer')\n    if lo is not None and value < lo:\n        raise ValueError(f'{label} below allowed range')\n    if hi is not None and value > hi:\n        raise ValueError(f'{label} above allowed range')\n    return value\n\n\ndef _strict_top6(value, label: str) -> list[int]:\n    if not isinstance(value, list) or len(value) != 6:\n        raise ValueError(f'{label} must contain exactly six numbers')\n    out = [_strict_int(x, label, lo=1, hi=60) for x in value]\n    if len(set(out)) != 6:\n        raise ValueError(f'{label} must contain six unique numbers')\n    return out\n\n\ndef _validate_freeze_event_against_artifact(fr: dict, frozen: dict, target: int) -> None:\n    target = _strict_int(target, 'target contest', lo=1)\n    if not isinstance(fr, dict) or not isinstance(frozen, dict):\n        raise ValueError('freeze event/artifact must be objects')\n    if _strict_int(fr.get('target_contest'), 'freeze event target', lo=1) != target:\n        raise ValueError('freeze event target mismatch')\n    if _strict_int(frozen.get('target_contest'), 'freeze artifact target', lo=1) != target:\n        raise ValueError('freeze artifact target mismatch')\n    if fr.get('frozen_before_result') is not True or fr.get('causal_cutoff') is not True:\n        raise ValueError('freeze event lacks causal flags')\n    if frozen.get('frozen_before_result') is not True or frozen.get('causal_cutoff') is not True:\n        raise ValueError('freeze artifact lacks causal flags')\n    event_cutoff = _strict_int(fr.get('cutoff_contest'), 'freeze event cutoff', lo=0)\n    artifact_cutoff = _strict_int(frozen.get('cutoff_contest'), 'freeze artifact cutoff', lo=0)\n    if event_cutoff != target - 1 or artifact_cutoff != event_cutoff:\n        raise ValueError('freeze cutoff mismatch')\n    if fr.get('data_sha256') != frozen.get('data_sha256'):\n        raise ValueError('freeze event/artifact data hash mismatch')\n\n    event_champion = _strict_top6(fr.get('champion_top6'), 'freeze event Champion top6')\n    event_challenger = _strict_top6(fr.get('challenger_top6'), 'freeze event Challenger top6')\n    artifact_champion = _strict_top6(frozen.get('champion', {}).get('top6'), 'freeze artifact Champion top6')\n    artifact_challenger = _strict_top6(frozen.get('challenger', {}).get('top6'), 'freeze artifact Challenger top6')\n    if event_champion != artifact_champion or event_challenger != artifact_challenger:\n        raise ValueError('freeze event top6 differs from frozen artifact')\n\n    snapshot = fr.get('snapshot')\n    challenger = frozen.get('challenger')\n    if not isinstance(snapshot, dict) or not isinstance(challenger, dict):\n        raise ValueError('freeze snapshot/challenger payload missing')\n    top_level_snapshot_keys = {\n        'signal_expansion_governance', 'sequential_prospective_proof', 'promotion_policy',\n        'independent_audit_policy', 'evidence_only_promotion_policy', 'promotion_lineage',\n    }\n    for key, observed in snapshot.items():\n        if key in challenger:\n            expected = challenger[key]\n        elif key in top_level_snapshot_keys and key in frozen:\n            expected = frozen[key]\n        else:\n            raise ValueError(f'freeze snapshot contains unbound field: {key}')\n        if observed != expected:\n            raise ValueError(f'freeze snapshot differs from artifact: {key}')\n\n    if fr.get('promotion_lineage') is not None and fr.get('promotion_lineage') != frozen.get('promotion_lineage'):\n        raise ValueError('freeze promotion lineage differs from artifact')\n    hashes = fr.get('hashes')\n    if not isinstance(hashes, dict) or not hashes:\n        raise ValueError('freeze component hashes missing')\n    for component, observed in hashes.items():\n        field = 'signal_state_sha256' if component == 'state' else f'{component}_sha256'\n        if field not in frozen or frozen.get(field) != observed:\n            raise ValueError(f'freeze component hash differs from artifact: {component}')\n\n\n"""
if insert_after not in s: raise SystemExit('import marker missing')
s=s.replace(insert_after,insert_after+helpers,1)

old_e="""def _next_e_value(ledger: dict, challenger_hits: int, champion_hits: int) -> float:\n    pairs = paired_events(ledger)\n    previous = float(pairs[-1][2].get('e_value_after', 1.0)) if pairs else 1.0\n    x = (float(challenger_hits) - float(champion_hits)) / 6.0\n    factor = 1.0 + E_BET_LAMBDA * x\n    if factor <= 0:\n        raise ValueError('invalid e-process factor')\n    return previous * factor\n"""
new_e="""def _next_e_value(ledger: dict, challenger_hits: int, champion_hits: int) -> float:\n    challenger_hits = _strict_int(challenger_hits, 'challenger hits', lo=0, hi=6)\n    champion_hits = _strict_int(champion_hits, 'champion hits', lo=0, hi=6)\n    pairs = paired_events(ledger)\n    previous = pairs[-1][2].get('e_value_after', 1.0) if pairs else 1.0\n    if isinstance(previous, bool) or not isinstance(previous, (int, float)) or not math.isfinite(float(previous)) or float(previous) < 0.0:\n        raise ValueError('previous e-value must be finite and non-negative')\n    previous = float(previous)\n    x = (challenger_hits - champion_hits) / 6.0\n    factor = 1.0 + E_BET_LAMBDA * x\n    if not math.isfinite(factor) or factor <= 0.0:\n        raise ValueError('invalid e-process factor')\n    result = previous * factor\n    if not math.isfinite(result) or result < 0.0:\n        raise ValueError('invalid e-process result')\n    return result\n"""
if old_e not in s: raise SystemExit('e-value marker missing')
s=s.replace(old_e,new_e,1)

old_freeze="""    freeze_file = Path(fr['freeze_file'])\n    if not freeze_file.exists() or sha256(freeze_file) != fr['freeze_sha256']:\n        raise ValueError('frozen artifact hash mismatch')\n\n    df = pd.read_excel(result_data)\n"""
new_freeze="""    freeze_file = Path(fr['freeze_file'])\n    if not freeze_file.exists() or sha256(freeze_file) != fr['freeze_sha256']:\n        raise ValueError('frozen artifact hash mismatch')\n    frozen = json.loads(freeze_file.read_text(encoding='utf-8'))\n    if not isinstance(frozen, dict):\n        raise ValueError('frozen artifact must be an object')\n    _validate_freeze_event_against_artifact(fr, frozen, target)\n\n    df = pd.read_excel(result_data)\n"""
if old_freeze not in s: raise SystemExit('freeze load marker missing')
s=s.replace(old_freeze,new_freeze,1)

old_actual="""    r = row.iloc[0]\n    actual = sorted(int(r[f'Bola{i}']) for i in range(1, 7))\n    if len(set(actual)) != 6 or actual[0] < 1 or actual[-1] > 60:\n        raise ValueError('invalid result')\n    actual_set = set(actual)\n    champion_top6 = [int(x) for x in fr['champion_top6']]\n    challenger_top6 = [int(x) for x in fr['challenger_top6']]\n"""
new_actual="""    r = row.iloc[0]\n    raw_actual = [r[f'Bola{i}'] for i in range(1, 7)]\n    actual = []\n    for value in raw_actual:\n        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)) or not float(value).is_integer():\n            raise ValueError('official result must contain integer lottery numbers')\n        actual.append(int(value))\n    actual = sorted(_strict_top6(actual, 'official result'))\n    actual_set = set(actual)\n    champion_top6 = _strict_top6(frozen['champion']['top6'], 'frozen Champion top6')\n    challenger_top6 = _strict_top6(frozen['challenger']['top6'], 'frozen Challenger top6')\n"""
if old_actual not in s: raise SystemExit('actual marker missing')
s=s.replace(old_actual,new_actual,1)

# Use canonical frozen-derived snapshot after full equality check.
s=s.replace("    snapshot = fr['snapshot']\n", "    snapshot = fr['snapshot']\n",1)
